const page = (i) => 'data:text/html;charset=utf-8,' + encodeURIComponent('<!doctype html><title>p' + i + '</title><main><p id=marker>page-' + i + '-body</p></main>');
const markers = [];
for (let i = 0; i < 6; i++) {
  const tab = await openTab(page(i));
  markers.push(await tab.evaluate(() => document.querySelector('#marker').textContent));
  await tab.close();
}
console.log('EVAL_JSON ' + JSON.stringify({ count: markers.length, markers }));

